add(nr=301, id="10439135691018", orig_titel="Pilatesring TUNTURI Pilates Ring, lila",
 fakta="Pilatesring TUNTURI Pilates Ring, lila. Tunturi Pilatesring är ett utmärkt verktyg för att förbättra dina träningsresultat. Den bekväma, mjuka ringen ger dig ett bra grepp och ringen i sig stöder dina övningar. Perfekt för armar, ben och ryggmuskler. Mer information: Material: glasfiber och skum. Vikt: 340g. Storlek: 40 x 37 x 5 cm. Diameter: 50cm. \"Må bättre varje dag\" - det är Tuntur's motto. Våra rötter går tillbaka till 1922 då två bröder grundade en cykelaffär i Finland. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödjande appar. Vårt produktsortiment utökas och förbättras ständigt, och vi erbjuder kvalitetsprodukter och utmärkta garantier. Märke Tunturi. Typ Stretchband. Tagg På beställning. Variant Default Title, SKU 14TUSPI005",
 titel="Pilatesring Tunturi, glasfiber och skum, lila",
 seo_title="Pilatesring Tunturi, lila",
 meta="Tunturi Pilatesring i lila, tillverkad av glasfiber och skum. Ringen är mjuk, väger 340 g och har ett grepp som stöder övningarna. Artikelnummer 14TUSPI005.",
 intro="Tunturi Pilatesring är en mjuk pilatesring i glasfiber och skum som väger 340 g. Ringen är lila.",
 passar=["Dig som vill ha en mjuk ring som ger grepp vid övningar","Övningar för armar, ben och ryggmuskler","Dig som vill ha en lätt ring på 340 g"],
 spec=["Material: glasfiber och skum","Vikt: 340 g","Färg: lila","Artikelnummer: 14TUSPI005"],
 faq=[], marke=None,
 motivering="Fakta ur källan. Utelämnat: \"utmärkt verktyg för att förbättra dina träningsresultat\", \"perfekt\", Tunturis märkestext (1922, Finland, motto, \"frisk och vältränad kropp\", \"kvalitetsprodukter och utmärkta garantier\"). Båda måtten (storlek och diameter) utelämnas eftersom de motsäger varandra.",
 att_bekrafta=["Källan anger både Storlek 40 x 37 x 5 cm och Diameter 50 cm. En ring med diameter 50 cm ryms inte i 40 x 37 cm. Fastställ rätt mått.","Taggen \"På beställning\" tyder på beställningsvara. Standardblock för beställningsvaror bör användas om det stämmer.","Produkttypen i butiken är Stretchband, vilket inte stämmer med en pilatesring. Bekräfta typ.","Lila kommer från titeln. Källtexten nämner inte färgen."])

add(nr=302, id="10472215347466", orig_titel="Magträningshjul TUNTURI Double Exercise Wheel",
 fakta="Magträningshjul TUNTURI Double Exercise Wheel. Lägg till en extra dimension till din träning: bygg muskelstyrka och förbättra din balans. Tunturi magträningshjul tränar din överkropp såväl som din bål. Du kan kombinera styrke- och balansträning utan att tappa greppet. Dubbelhjuldesignen och de breda handtagen hjälper dig att snabbt bemästra tekniken. Må bättre varje dag. Det är Tunturis motto. Våra rötter finns i Finland, där två bröder grundade en cykelaffär 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöttar dig på din resa mot en frisk, vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödappar. Det är ett ständigt växande och förbättrande sortiment av högkvalitativa produkter med utmärkta garantier. Ytterligare information: Mått (PLK): 18 x 24 x 18,5 cm. Vikt: 0,58 kg. Material: syntetiskt. Märke Tunturi. Typ Magträningshjul. Variant Default Title, SKU 14TUSCL245",
 titel="Magträningshjul Tunturi Double Exercise Wheel, dubbelhjul",
 seo_title="Magträningshjul Tunturi, dubbelhjul",
 meta="Tunturi Double Exercise Wheel är ett magträningshjul med dubbelhjuldesign och breda handtag. Måtten är 18 x 24 x 18,5 cm och vikten 0,58 kg.",
 intro="Tunturi Double Exercise Wheel är ett magträningshjul med dubbelhjuldesign och breda handtag. Hjulet tränar överkropp och bål.",
 passar=["Dig som vill träna överkropp och bål","Dig som vill ha ett hjul med dubbelhjuldesign och breda handtag","Dig som vill kombinera styrke- och balansträning"],
 spec=["Design: dubbelhjul med breda handtag","Mått (PLK): 18 x 24 x 18,5 cm","Vikt: 0,58 kg","Material: syntetiskt","Artikelnummer: 14TUSCL245"],
 faq=[], marke=None,
 motivering="Fakta ur källan. Utelämnat: \"bygg muskelstyrka och förbättra din balans\" (effektlöfte), \"bemästra tekniken snabbt\", Tunturis märkestext (Finland, 1922, motto, kvalitetsprodukter).",
 att_bekrafta=["Vad \"PLK\" betyder (troligen längd, bredd, höjd) framgår inte; texten använder källans uttryck.","Källan anger inte vilket syntetiskt material hjulen och handtagen är gjorda av.","Maxbelastning saknas i källan."])

add(nr=303, id="10472303689994", orig_titel="TUNTURI Gymnastikboll 90cm, Anti-Burst, Mint",
 fakta="TUNTURI Gymnastikboll 90cm, Anti-Burst, Mint. Om du letar efter en gymnastikboll som inte bara tar din träning till nästa nivå, utan också är lämplig för yoga, stretching och kanske till och med att sitta vid ett skrivbord, är Tunturi Gymball ett utmärkt val! Tunturi Gymball är designad för att stödja vikter upp till 220 kg, vilket garanterar hållbarhet och stabilitet i varje rörelse. Välj rätt storlek på bollen för din längd: 55 cm - lämplig för längder mellan 155-165 cm. 65 cm - lämplig för längd 166-178 cm. 75 cm - lämplig för längder 179-190 cm. 90 cm - lämplig för längd > 190 cm. Tillverkaren är Tunturi. Detaljer: Diameter: 90 cm. Produktvikt: 1,5 kg. Bärförmåga: 220 kg. Produkten finns på Tunturis webbplats. Märke Tunturi. Typ Konditionsträning & Fitness. Variant Default Title, SKU 14TUSFU367",
 titel="Gymnastikboll Tunturi Gymball, 90 cm, Anti-Burst, mint",
 seo_title="Gymnastikboll Tunturi Gymball, 90 cm",
 meta="Tunturi Gymball är en gymnastikboll med diameter 90 cm, avsedd för längd över 190 cm. Bollen väger 1,5 kg och har en bärförmåga på 220 kg. Färg: mint.",
 intro="Tunturi Gymball är en gymnastikboll med diameter 90 cm och en bärförmåga på 220 kg. Storleken 90 cm är avsedd för längd över 190 cm.",
 passar=["Dig som är längre än 190 cm","Yoga och stretching","Dig som vill sitta på bollen vid ett skrivbord"],
 spec=["Diameter: 90 cm","Produktvikt: 1,5 kg","Bärförmåga: 220 kg","Storlek 90 cm: lämplig för längd över 190 cm","Färg: mint","Artikelnummer: 14TUSFU367"],
 faq=[("Vilken storlek ska jag välja?","Enligt källan är 55 cm lämplig för längd 155-165 cm, 65 cm för 166-178 cm, 75 cm för 179-190 cm och 90 cm för längd över 190 cm.")], marke=None,
 motivering="Fakta ur källan. Utelämnat: \"tar din träning till nästa nivå\", \"utmärkt val\", \"garanterar hållbarhet och stabilitet\". Länken till Tunturis webbplats tas inte med.",
 att_bekrafta=["Produkten har status DRAFT i butiken.","\"Anti-Burst\" står bara i titeln, inte i beskrivningen. Bekräfta att bollen är sprängsäker innan det används som egenskap.","Färgen Mint kommer från titeln.","Om pump ingår framgår inte.","Källan anger bärförmåga 220 kg. Bekräfta att uppgiften är rätt innan den publiceras."])

add(nr=304, id="10472310997258", orig_titel="Massage roller TUNTURI Yoga Grid Foam Roller, 33cm, Grå",
 fakta="Massage roller TUNTURI Yoga Grid Foam Roller, 33cm, Grå. Tunturi Yoga Grid Foam Roller är ett utmärkt verktyg för att bibehålla musklernas flexibilitet och massera muskler före, under och efter träning. Tillverkaren är: Tunturi. Detaljer: Mått. Vikt: 850 gram. Material: EVA, PVC. Märke Tunturi. Typ Konditionsträning & Fitness. Variant Default Title, SKU 14TUSYO087",
 titel="Skumrulle Tunturi Yoga Grid, 33 cm, grå",
 seo_title="Skumrulle Tunturi Yoga Grid, 33 cm",
 meta="Tunturi Yoga Grid är en skumrulle på 33 cm i grått. Rullen är tillverkad av EVA och PVC och väger 850 gram. Artikelnummer 14TUSYO087.",
 intro="Tunturi Yoga Grid är en grå skumrulle på 33 cm, tillverkad av EVA och PVC. Den väger 850 gram.",
 passar=["Dig som söker en skumrulle på 33 cm","Dig som vill ha en rulle i EVA och PVC"],
 spec=["Längd: 33 cm","Vikt: 850 gram","Material: EVA, PVC","Färg: grå","Artikelnummer: 14TUSYO087"],
 faq=[], marke=None,
 motivering="Fakta ur källan. Utelämnat: \"utmärkt verktyg\", påståendena om flexibilitet och att massera muskler (effekt och massage). Längd 33 cm och färg grå kommer från titeln.",
 att_bekrafta=["Raden \"Mått\" i källan saknar värde. Bara 33 cm i titeln.","Källan anger inte om 33 cm är längd, och inte diameter. Jämför med ljusblå varianten (33 x 13 x 13 cm).","Titeln i butiken säger \"Massage roller\". Texten använder skumrulle."])

