add(nr=307, id="10462794547466", orig_titel="Handledvikter TUNTURI Handledvikter 1kg",
 fakta="Handledvikter TUNTURI Handledvikter 1kg. Få en ännu effektivare träning med dessa Tunturi justerbara fot- och handledsvikter! Fäst dem på anklarna eller handlederna och låt musklerna arbeta hårdare med den extra vikten. Vikterna är lätta att fästa och ta bort med en snabbfäste. Använd dem för träning, yoga, tennis, kampsport, skridskoåkning eller fotbollsträning. Kort sagt, det finns gott om alternativ. Vikterna sitter åt bekvämt och materialet är mjukt för optimal komfort under träning. Fördelar med Tunturi justerbara fot- och handledsvikter - 2 x 1,0 kg. - Ett billigt och enkelt sätt att öka intensiteten i din träning. - Tillverkade av stark och mjuk neopren: känns bekvämt. - Lätta att bära och använda var du än går. - Lämpliga för en mängd olika sportaktiviteter: från träning till kampsport. Lägg till en extra dimension till din träning med dessa Tunturi justerbara fot- och handledsvikter. Lägg till en extra dimension till din träning. Må bättre varje dag. Det är Tunturis motto. Våra rötter finns i Finland, där två bröder grundade en cykelbutik 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödsystem. Det är ett ständigt växande och uppgraderande sortiment av högkvalitativa produkter och fantastiska garantier. Omfattande specifikationer: Mått (LWH): 21,5 x 7,5 x 3,2 cm. Vikt: 2 x 1,0 kg. Vikt: 2 x 1,0 kg. Storlek: 1 storlek. 1,0 x 1,0WH. Kardborrefäste. Färg: grå | Svart. Material: neopren. Märke Tunturi. Typ Extra vikter, tillbehör. Variant Default Title, SKU 14TUSCL240",
 titel="Fot- och handledsvikter Tunturi, justerbara, 2 x 1 kg",
 seo_title="Fot- och handledsvikter Tunturi, 2 x 1 kg",
 meta="Justerbara fot- och handledsvikter från Tunturi, 2 x 1 kg, i neopren med kardborrefäste. Vikterna fästs på anklar eller handleder. Storlek: en storlek.",
 intro="Tunturi justerbara fot- och handledsvikter säljs som ett par, 2 x 1 kg, och fästs på anklarna eller handlederna. De är tillverkade av neopren och har kardborrefäste.",
 passar=["Dig som vill ha extra vikt på anklar eller handleder","Träning, yoga, tennis, kampsport, skridskoåkning eller fotbollsträning","Dig som vill ha vikter i neopren med kardborrefäste"],
 spec=["Vikt: 2 x 1 kg","Mått (LWH): 21,5 x 7,5 x 3,2 cm","Storlek: en storlek","Fäste: kardborrefäste","Material: neopren","Färg: grå | svart","Artikelnummer: 14TUSCL240"],
 faq=[], marke=None,
 motivering="Fakta ur källan. Utelämnat: \"ännu effektivare träning\", \"billigt\", \"optimal komfort\", \"fantastiska garantier\", Tunturis märkestext, den dubbla vikt-raden och den obegripliga raden \"1,0 x 1,0WH\".",
 att_bekrafta=["Källan nämner både \"snabbfäste\" i texten och \"kardborrefäste\" i specifikationen. Texten använder kardborrefäste.","Raden \"1,0 x 1,0WH\" är obegriplig och är utelämnad.","Färg \"grå | svart\": om det är två färgval eller en tvåfärgad produkt framgår inte, och butiken har bara en variant.","Titeln i butiken lyder \"1kg\" men källan anger 2 x 1,0 kg. Bekräfta om 1 kg gäller per vikt."])

add(nr=308, id="10472203321610", orig_titel="Träningsset Tunturi Pro Suspension Trainer Set",
 fakta="Träningsset Tunturi Pro Suspension Trainer Set. Träna på stranden, i skogen eller inomhus, allt är möjligt med Tunturi Pro Suspension träningsset. Satsen innehåller en mängd träningsutrustning för att träna din egen kroppsvikt. Till exempel kan du fästa utrustningen vid en dörr, ett träd eller en stång. Långa huvudlinor med D-ringar utgör en bas som du kan komplettera med ringar, handtag eller benremmar. Du kan enkelt förlänga eller förkorta hängtränaren genom att fästa tillbehör vid en annan D-ring. Den medföljande vattenkokaren gör att du kan utföra mobila suspensionövningar. Fördelar med Tunturi Pro Suspension Trainer Set: Variation av träningsövningar för att passa din egen kroppsvikt. Lätt att montera med en ankarlina. Kompakt och lätt förpackning: lätt att bära med sig. Kompakt och lätt, lätt att bära Kompakt och lätt att använda. Kompakt och lättanvänd, lättanvänd förpackning för ditt träningsprogram. Vikt: 4,5 kg. Ingår: 2 benremmar | 2 handtag | 2 huvudlinor, var och en med 10 metalld-ringar, 2 ankelförare | 2 ringar | 1 vattenkokare. Inkluderar träningsplan. Inkluderar bärväska och 2 nylonväskor. Fullt justerbar. Färg: Svart-röd. Material: EVA. Färg: Svart/vit; PVC; PVC: PVC; Tunturi på Må bättre varje dag. Svart, svart, svart läder, svart läder, svart. Våra rötter går tillbaka till Finland, där två bröder grundade en cykelaffär 1922. Nu, mer än 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödjande appar. Det är ett sortiment som ständigt utökas och växer, med kvalitetsprodukter och bra garantier. Märke Tunturi. Typ Tillbehör. Variant Default Title, SKU 14TUSCF001",
 titel="Hängtränare Tunturi Pro Suspension Trainer Set, 4,5 kg",
 seo_title="Hängtränare Tunturi Pro Suspension Trainer",
 meta="Tunturi Pro Suspension Trainer Set är en hängtränare för träning med egen kroppsvikt. I setet ingår bland annat 2 handtag, 2 ringar och 2 benremmar. Vikt 4,5 kg.",
 intro="Tunturi Pro Suspension Trainer Set är ett träningsset för träning med den egna kroppsvikten. Utrustningen kan fästas vid en dörr, ett träd eller en stång.",
 passar=["Träning med den egna kroppsvikten","Dig som vill kunna fästa utrustningen vid en dörr, ett träd eller en stång","Dig som vill komplettera huvudlinorna med ringar, handtag eller benremmar"],
 spec=["Ingår: 2 benremmar, 2 handtag, 2 huvudlinor med 10 D-ringar i metall vardera, 2 ringar","Ingår även: träningsplan, bärväska och 2 nylonväskor","Vikt: 4,5 kg","Fullt justerbar","Fästs med ankarlina","Artikelnummer: 14TUSCF001"],
 faq=[("Var kan jag fästa utrustningen?","Enligt källan vid en dörr, ett träd eller en stång.")], marke=None,
 motivering="Fakta ur källan. Utelämnat: delar av listan över det som ingår (\"2 ankelförare\", \"1 vattenkokare\") och meningen om vattenkokaren, eftersom orden ser maskinöversatta ut. Färg och material utelämnas eftersom de motsäger sig. Upprepade, trasiga punkter (\"Kompakt och lätt...\") och märkestexten är utelämnade.",
 att_bekrafta=["Källan har trasig text (\"metalld-ringar\", \"ankelförare\", \"vattenkokare\", \"Svart, svart, svart läder\"). Troligen maskinöversättning. Datablad behövs för vad som ingår.","Färg anges som \"Svart-röd\" och som \"Svart/vit\", och material som EVA och PVC. Fastställ rätt färg och material.","\"10 metalld-ringar\" har tolkats som 10 D-ringar i metall. Bekräfta.","Maxbelastning saknas i källan. Det är en utrustning man hänger i, så uppgiften bör finnas innan försäljning."])

add(nr=309, id="10486629597450", orig_titel="Vibrationsplatta TUNTURI Cardio Fit V10",
 fakta="Vibrationsplatta TUNTURI Cardio Fit V10. Så här fungerar vibrationsplattan: vibrationerna kastar dig ur balans så att musklerna arbetar för att hålla dig balanserad. Tekniskt sett kan du träna utan att behöva röra dig. Med vibrationsplattan kan du också intensifiera olika övningar som knäböj, utfall, armcurls och bålövningar för bättre resultat. Dessutom kan du även använda vibrationsplattan för att slappna av efter ditt vanliga träningspass. Vibrationsplattan har en avtagbar sits som du kan använda för olika övningar. Tunturi Cardio Fit V10 använder oscillationer – det är som en gungande rörelse som kastar din kropp ur balans, så dina muskler måste arbeta hårdare för att hålla dig balanserad. Med oscillation utsätts dina ryggkotor för mindre stress än med vibration, till exempel. Specifikt: Funktion: oscillation. Mått: 58 x 35 x 33 cm (inklusive sits). Produktvikt: 11 kg. Maximal användarvikt: 150 kg. Vibrationsplattan levereras med två träningsgummiband med handtag, en stång och handtag för armförlängningar. Märke Tunturi. Typ Konditionsträning & Fitness. Tagg På beställning. Variant Default Title, SKU 19TCFV1000",
 titel="Vibrationsplatta Tunturi Cardio Fit V10, oscillation, sits",
 seo_title="Vibrationsplatta Tunturi Cardio Fit V10",
 meta="Tunturi Cardio Fit V10 är en vibrationsplatta med oscillation och avtagbar sits. Maximal användarvikt 150 kg. Med två träningsgummiband med handtag och en stång.",
 intro="Tunturi Cardio Fit V10 är en vibrationsplatta som arbetar med oscillation. Den har en avtagbar sits och maximal användarvikt är 150 kg.",
 passar=["Övningar som knäböj, utfall, armcurls och bålövningar","Dig som vill ha en avtagbar sits till olika övningar","Användare upp till 150 kg"],
 spec=["Funktion: oscillation","Mått: 58 x 35 x 33 cm (inklusive sits)","Produktvikt: 11 kg","Maximal användarvikt: 150 kg","Avtagbar sits","Ingår: två träningsgummiband med handtag, en stång och handtag för armförlängningar","Artikelnummer: 19TCFV1000"],
 faq=[("Vad ingår?","Plattan levereras med två träningsgummiband med handtag, en stång och handtag för armförlängningar.")], marke=None,
 motivering="Fakta ur källan. Utelämnat: att man kan träna utan att röra sig, \"för bättre resultat\", att slappna av efter träning, och jämförelsen med vibration (\"mindre stress\" på ryggkotor), som är hälsopåståenden.",
 att_bekrafta=["Taggen \"På beställning\" tyder på beställningsvara. Standardblock för beställningsvaror bör användas om det stämmer.","Källan använder både \"vibration\" och \"oscillation\" om samma platta. Titeln följer butikens typ (vibrationsplatta).","Effekt, hastighetssteg och program saknas i källan. Eventuella kontraindikationer eller varningar för användare saknas också och bör kontrolleras mot tillverkarens datablad."])

