add(nr=311, id="10411720704266", orig_titel="Leg protectors TUNTURI Allround Shinguard",
 fakta="Leg protectors TUNTURI Allround Shinguard. Skydda ditt ben. Boxning kan vara tufft. Därför är det viktigt att skydda dig så bra som möjligt. Oavsett om du är en nybörjare i boxning eller redan har mycket erfarenhet; att skydda din kropp är avgörande för att undvika skador. Skydda ditt ben med dessa benskydd. De har en skumvaddering som absorberar sparkar från dig. Benskydden är förformade, sitter perfekt och glider inte, tack vare elastiska band och en stadig kil. Fördelar: Lämpliga för nybörjare. Lätta. Tillverkade av andningsbar bomull. Förformade. Skyddar även foten. Unisex. Fotskydd: Dessa benskydd är lätta och lämpliga för olika kampsporter som boxning, thaiboxning och mixed martial arts. Foten måste också tåla mycket sparkar. Dessa benskydd täcker därför även foten för att förhindra skador. Benskydd är lätta att ta på och av, som en sorts strumpa eller stövel, där du drar åt de elastiska banden för att förhindra att de sjunker eller glider. Om Tunturi: Må bättre varje dag. Det är Tunturis motto. Våra rötter finns i Finland, där två bröder grundade en cykelbutik 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödsystem. Det är ett ständigt växande och uppgraderande sortiment av högkvalitativa produkter och bra garantier. Tekniska data översikt: Vikt: 102 gr. Färg: svart. Material: bomull. Set med två skydd. Fästning baktill. Storlek: XXS (benlängd: 28,5 cm). Finns i XXS, XS, S, M, L och XL. Produktkod: 14TUSBO088. EAN-kod: 8717842034002. Märke Tunturi. Typ Boxningsutrustning. Varianter S / black (SKU 14TUSBO082), XL / black (SKU 14TUSBO085), XS / black (SKU 14TUSBO087), XXS / black (SKU 14TUSBO088)",
 titel="Benskydd Tunturi Allround, bomull, svart, set om 2",
 seo_title="Benskydd Tunturi Allround, svart",
 meta="Tunturi Allround är benskydd i bomull med skumvaddering, elastiska band och fästning baktill. Skydden är förformade, täcker även foten och säljs som set om 2.",
 intro="Tunturi Allround är förformade benskydd i bomull med skumvaddering och elastiska band. De täcker även foten och säljs som set med två skydd.",
 passar=["Boxning, thaiboxning och mixed martial arts","Nybörjare i kampsport","Dig som vill ha benskydd som även täcker foten"],
 spec=["Set med två skydd","Material: bomull","Färg: svart","Skumvaddering, förformade, elastiska band","Fästning baktill","Storlekar i butiken: XXS, XS, S, XL","Storlek XXS: benlängd 28,5 cm","Vikt: 102 gr (enligt källan)"],
 faq=[("Vilka storlekar finns?","Källan anger att benskydden finns i XXS, XS, S, M, L och XL. I butiken finns just nu XXS, XS, S och XL.")], marke=None,
 motivering="Fakta ur källan. Utelämnat: att skydden \"absorberar sparkar\", att de förhindrar eller undviker skador, \"sitter perfekt\", \"avgörande\" och \"andningsbar\" (skyddsresp. egenskapspåståenden utan belägg), Tunturis märkestext och EAN/produktkod i löptext.",
 att_bekrafta=["Källan anger storlekarna XXS-XL men butiken har bara S, XL, XS och XXS som varianter.","Vikten 102 gr och benlängden 28,5 cm gäller storlek XXS enligt källan. Vikt för övriga storlekar saknas.","Storlek XXS med benlängd 28,5 cm kan vara en barnstorlek. Källan säger inget om målgrupp utöver \"Unisex\" och \"Lämpliga för nybörjare\".","Skyddsprodukt. Skyddsegenskaper har inte skrivits. Bekräfta vilka påståenden som får användas.","Titeln i butiken lyder \"Leg protectors\". Texten använder benskydd, som källan själv gör."])

add(nr=312, id="10462778392842", orig_titel="TUNTURI SC30 Smartvåg med app, svart",
 fakta="TUNTURI SC30 Smartvåg med app, svart. Tunturi SC30 vågen är mer än bara en viktenhet. Den har en rad funktioner som hjälper dig att få en överblick över din hälsa. Med sin eleganta design är denna våg ett oumbärligt verktyg för alla som vill förbättra sin hälsa. Vågen kan anslutas till din telefon via den kostnadsfria Fitdays-appen. Tunturi SC30 Smartvåg mäter: vikt, kroppsmasseindex (BMI), fettprocent, muskelmassa, fettfri massa, subkutant fett, intraabdominellt fett, kroppsvätskor, skelettmuskelvikt, kroppsålder, protein, BMR, benvikt, muskelprocent. Tillverkare . Detaljer: Mått: 26 x 26 x 1,8 cm. Vikt: 1 kg. Strömförsörjning: 2 x AAA-batterier (ingår). Maximal belastningsvikt: 180 kg. Märke Tunturi. Typ Konditionsträning & Fitness. Variant Default Title, SKU 14TUSSP001",
 titel="Smartvåg Tunturi SC30 med app, svart",
 seo_title="Smartvåg Tunturi SC30 med app",
 meta="Tunturi SC30 är en smartvåg i svart som ansluts till telefonen via Fitdays-appen. Vågen mäter 26 x 26 x 1,8 cm och har en maximal belastningsvikt på 180 kg.",
 intro="Tunturi SC30 är en smartvåg i svart som kan anslutas till telefonen via Fitdays-appen. Vågen drivs med 2 x AAA-batterier som ingår.",
 passar=["Dig som vill koppla vågen till telefonen via Fitdays-appen","Dig som vill följa mått som vikt, BMI och fettprocent","Användare upp till 180 kg"],
 spec=["Mäter: vikt, kroppsmasseindex (BMI), fettprocent, muskelmassa, fettfri massa, subkutant fett, intraabdominellt fett, kroppsvätskor, skelettmuskelvikt, kroppsålder, protein, BMR, benvikt, muskelprocent","App: Fitdays (kostnadsfri)","Mått: 26 x 26 x 1,8 cm","Vikt: 1 kg","Strömförsörjning: 2 x AAA-batterier (ingår)","Maximal belastningsvikt: 180 kg","Färg: svart","Artikelnummer: 14TUSSP001"],
 faq=[("Vilken app används?","Vågen ansluts till telefonen via den kostnadsfria Fitdays-appen.")], marke=None,
 motivering="Fakta ur källan. Utelämnat: att vågen hjälper dig få överblick över din hälsa, \"oumbärligt\" och \"förbättra sin hälsa\", \"elegant design\". Färgen svart kommer från titeln.",
 att_bekrafta=["Tillverkarraden i källan är tom.","Källan anger inte hur mätningarna görs eller hur noggranna de är, och inte vilka telefoner appen stöder.","Mätvärdena som kroppsfett och kroppsvätskor bör kontrolleras mot datablad innan de presenteras som mätbara."])

add(nr=313, id="10472216363274", orig_titel="Massagebollar Tunturi Korkmassagebollset",
 fakta="Massagebollar Tunturi Korkmassagebollset. Det 100% naturliga Tunturi massagebollsetet är den perfekta följeslagaren för att koppla av efter ett träningspass. Du kan massera dina muskler utan hjälp av någon annan. Massagen stimulerar blodcirkulationen, vilket hjälper till att återställa och påskynda återhämtningen av djupa muskelområden. Denna uppsättning massagebollar är lämplig för både lättare och djupare massage över hela kroppen, samt för triggerpunkter. Fördelar: Tillverkad av 100% naturligt och biologiskt nedbrytbart material. 100% naturlig och naturlig fiber, 100% naturlig och naturlig råvara, främjar och påskyndar återhämtningen av djupa muskelområden. Lämplig för hela kroppen. Doftfri och kemikaliefri. Hygienisk och immun mot mögel. 100% naturlig Båda massagebollarna är gjorda av kork, ett 100% återvinningsbart och miljövänligt material. Korken är slitstark, har en behaglig textur och är skonsam mot huden. Massagebollarna är kemikaliefria och immuna mot mögel, vilket säkerställer säker och hygienisk användning. \"Må bättre varje dag\" - det är Tuntur-mottot. Våra rötter går tillbaka till 1922, då två bröder grundade en cykelbutik i Finland. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödjande appar. Specifikationer: Set med två. Två set om två: 5 och 6,5 cm diameter. Vikt: 60 g. Material och färg: kork. Märke Tunturi. Typ Massage. Variant Default Title, SKU 14TUSYO060",
 titel="Korkbollar Tunturi Korkmassagebollset, set med 2",
 seo_title="Korkbollar Tunturi, set med 2",
 meta="Tunturi korkbollar i set med två, med diameter 5 och 6,5 cm. Bollarna är gjorda av kork och väger 60 g. Artikelnummer 14TUSYO060.",
 intro="Tunturi Korkmassagebollset är ett set med två bollar av kork. Diametrarna anges som 5 och 6,5 cm och vikten som 60 g.",
 passar=["Dig som söker bollar i kork","Dig som vill ha bollar i två storlekar, 5 och 6,5 cm"],
 spec=["Set med två","Diameter: 5 och 6,5 cm","Vikt: 60 g","Material och färg: kork","Artikelnummer: 14TUSYO060"],
 faq=[], marke=None,
 motivering="Fakta ur källan. Utelämnat: alla hälso- och effektpåståenden (blodcirkulation, återhämtning, triggerpunkter, hud), miljöpåståenden (\"biologiskt nedbrytbart\", \"miljövänligt\", \"återvinningsbart\"), \"100 % naturlig\", \"kemikaliefri\", \"immun mot mögel\", \"perfekt\" och märkestexten. Ordet massage används inte i texten.",
 att_bekrafta=["Källan säger både \"Set med två\" och \"Två set om två\". Antalet bollar (2 eller 4) är oklart. Texten använder \"set med två\" som i titeln på de flesta ställen och anger inte antal totalt.","Om diametrarna 5 och 6,5 cm gäller var sin boll eller olika set framgår inte.","Titeln i butiken lyder \"Massagebollar\". Texten använder \"korkbollar\" för att undvika massage-påståenden. Bekräfta om massage får användas i titeln.","Miljöpåståendena kräver belägg innan de kan användas."])

add(nr=314, id="10472218263818", orig_titel="Armband TUNTURI LED Armlight Röd",
 fakta="Armband TUNTURI LED Armlight Röd. Att springa på en naturskön väg, promenera med hunden, en promenad i skogen vid solnedgången. Det är skönt att vara utomhus tidigt på morgonen eller på kvällen, men det är viktigt att synas för andra. Olyckor kan lätt inträffa, särskilt när det är mörkt. Därför, när du är utomhus, bär denna Tunturi Armlight. De starka LED-lamporna syns på långt håll. Armlight tål alla väderförhållanden och är lätt att fästa på överarmen. Tillverkaren är Tunturi. Mer information: Mått: 33,5 x 8 x 2 cm. Produktvikt: 45 g. 33,5 cm - vikt: 33,5 kg - 45,5 cm - levereras med 2x CR2032-batterier (utbytbara). Batteritid: 100 timmar blinkande | 70 timmar fast sken. Material: syntetiskt (elastiskt). Märke Tunturi. Typ Tillbehör. Variant Default Title, SKU 14TUSRU176",
 titel="Armband Tunturi LED Armlight, röd",
 seo_title="Armband Tunturi LED Armlight, röd",
 meta="Tunturi LED Armlight är ett rött armband med LED-lampor som fästs på överarmen. Batteritid 100 timmar blinkande eller 70 timmar fast sken. Mått 33,5 x 8 x 2 cm.",
 intro="Tunturi LED Armlight är ett rött armband med LED-lampor som fästs på överarmen. Batteritiden är 100 timmar vid blinkande ljus och 70 timmar vid fast sken.",
 passar=["Promenader och löpning utomhus","Dig som vill ha ett armband med LED-lampor som fästs på överarmen"],
 spec=["Mått: 33,5 x 8 x 2 cm","Produktvikt: 45 g","Batteritid: 100 timmar blinkande, 70 timmar fast sken","Material: syntetiskt (elastiskt)","Färg: röd","Artikelnummer: 14TUSRU176"],
 faq=[("Hur länge räcker batteriet?","Enligt källan 100 timmar vid blinkande ljus och 70 timmar vid fast sken.")], marke=None,
 motivering="Fakta ur källan. Utelämnat: säkerhetsresonemanget (olyckor, mörker), \"starka LED-lampor syns på långt håll\" och \"tål alla väderförhållanden\" (säkerhets- och prestandapåståenden utan belägg), samt den trasiga raden om batterier. Färgen röd kommer från titeln.",
 att_bekrafta=["Raden \"33,5 cm - vikt: 33,5 kg - 45,5 cm - levereras med 2x CR2032-batterier (utbytbara)\" är trasig (vikt 33,5 kg är orimlig). Den är utelämnad, inklusive batterityp och om batterierna ingår. Datablad behövs.","Det är en produkt för att synas i mörker. Bekräfta vilka påståenden om synlighet och väder som får användas.","Hur mycket armbandet går att justera (omkrets) framgår inte."])

add(nr=315, id="10472270266634", orig_titel="Ben- och armvikter TUNTURI Arm/Leg Weights 1.5kg",
 fakta="Ben- och armvikter TUNTURI Arm/Leg Weights 1.5kg. Gör ditt träningspass mer intensivt och utmanande genom att linda dessa Tunturi-vikter runt handlederna eller anklarna. Vikterna lägger extra belastning på dina muskler under sportaktiviteter som fitness, yoga, löpning eller fotboll. Ankels- och handledsvikter finns i flera modeller. Du kan börja med denna lätta version 2 x 1,5 kg. När det blir lättare kan du börja använda tyngre vikter. Fäst vikterna med en gaffellåsning. Fördelar med Tunturi arm-/benvikter - 2 x 1,5 kg. - Vikterna har en mjuk känsla och är bekväma att bära. - Ett enkelt och billigt sätt att intensifiera ditt träningspass. - Lätta att bära och använda på olika platser. Beställ Tunturi arm-/benvikter och ge ditt träningspass en extra dimension! Om Tunturi: Må bättre varje dag. Det är Tunturis motto. Våra rötter finns i Finland, där två bröder grundade en cykelbutik 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödsystem. Det är ett ständigt växande och uppgraderande sortiment av högkvalitativa produkter och fantastiska garantier. Översikt: Mått (LWH): 38,5 x 14 x 3,5 cm. Vikt: 2 x 1,5 kg. Med kardborreband. 1,5 x 2,5 cm (1,5 lb). En storlek. Set om 2. Färg: Svart | Grå. Material: nylon. Nylon. Finns även i andra vikter. Produktkod: 14TUSFU119. EAN-kod: 8717842020388. Märke Tunturi. Typ Extra vikter, tillbehör. Variant Default Title, SKU 14TUSFU119",
 titel="Ben- och armvikter Tunturi Arm/Leg Weights, 2 x 1,5 kg",
 seo_title="Ben- och armvikter Tunturi, 2 x 1,5 kg",
 meta="Tunturi Arm/Leg Weights är ben- och armvikter i nylon, set om 2 x 1,5 kg. De lindas runt handlederna eller anklarna. Finns även i andra vikter. En storlek.",
 intro="Tunturi Arm/Leg Weights är ben- och armvikter i nylon, sålda som set om 2 x 1,5 kg. Vikterna lindas runt handlederna eller anklarna.",
 passar=["Dig som vill lägga extra vikt på handleder eller anklar","Fitness, yoga, löpning eller fotboll","Dig som vill kunna byta till tyngre vikter, eftersom modellen finns i andra vikter"],
 spec=["Set om 2","Vikt: 2 x 1,5 kg","Mått (LWH): 38,5 x 14 x 3,5 cm","Material: nylon","Färg: svart | grå","Storlek: en storlek","Finns även i andra vikter","Artikelnummer: 14TUSFU119"],
 faq=[], marke=None,
 motivering="Fakta ur källan. Utelämnat: \"mer intensivt och utmanande\", \"billigt\", \"Beställ...\", \"fantastiska garantier\" och märkestexten. Fästsättet utelämnas eftersom källan motsäger sig. Raden \"1,5 x 2,5 cm (1,5 lb)\" är obegriplig och utelämnad.",
 att_bekrafta=["Källan anger både \"gaffellåsning\" och \"kardborreband\" som fäste. Fäste utelämnat tills det är bekräftat.","Raden \"1,5 x 2,5 cm (1,5 lb)\" är obegriplig.","Färg \"svart | grå\": två färgval eller tvåfärgad framgår inte, och butiken har bara en variant.","Titeln anger \"1.5kg\". Källan anger 2 x 1,5 kg."])
